const cfg = $('Set Config').first().json;
const errors = [];
const placeholders = [
  'PEGAR_SUPABASE_DEV_URL',
  'PEGAR_SUPABASE_DEV_ANON_KEY',
  'PEGAR_EMAIL_ADMIN_DEV',
  'PEGAR_PASSWORD_ADMIN_DEV',
  'PEGAR_CORREO_INTERNO_DE_PRUEBA',
  'PEGAR_CORREO_REMITENTE_DEV'
];
for (const [key, value] of Object.entries(cfg)) {
  if (typeof value === 'string' && placeholders.includes(value)) errors.push(`${key}_placeholder_not_replaced`);
}
if (!String(cfg.FLUX_DEV_SUPABASE_URL || '').startsWith('https://')) errors.push('invalid_supabase_url');
const requiredDevHost = 'scsirgbuqjcwoaxfacth.supabase.co';
if (!String(cfg.FLUX_DEV_SUPABASE_URL || '').includes(requiredDevHost)) errors.push('non_dev_supabase_host_not_allowed');
const privilegedKeyPattern = new RegExp('service' + '[_-]?' + 'role', 'i');
if (privilegedKeyPattern.test(String(cfg.FLUX_DEV_SUPABASE_ANON_KEY || ''))) errors.push('privileged_key_not_allowed');
if (cfg.EMAIL_PILOT_MODE !== true) errors.push('email_pilot_mode_must_be_true');
if (Number(cfg.MAX_EVENTS_PER_RUN) !== 1) errors.push('max_events_per_run_must_be_1');
if (cfg.SEND_TO_TEST_EMAIL_ONLY === true && cfg.SEND_TO_REAL_RECIPIENT === true) errors.push('recipient_mode_conflict');
if (cfg.SEND_TO_TEST_EMAIL_ONLY !== true && cfg.SEND_TO_REAL_RECIPIENT !== true) errors.push('recipient_mode_missing');
if (cfg.SEND_TO_TEST_EMAIL_ONLY === true && !String(cfg.TEST_RECIPIENT_EMAIL || '').includes('@')) errors.push('test_recipient_email_required');
if (!cfg.FLUX_DEV_MIN_CREATED_AT || Number.isNaN(new Date(cfg.FLUX_DEV_MIN_CREATED_AT).getTime())) errors.push('invalid_min_created_at');
if (errors.length) throw new Error(`CONFIG_INVALID: ${errors.join('; ')}`);
return [{ json: cfg }];

const cfg = $('Set Config').first().json;
const minTime = new Date(cfg.FLUX_DEV_MIN_CREATED_AT).getTime();
const pending = [];
for (const item of $input.all()) {
  const value = item.json;
  if (Array.isArray(value)) pending.push(...value);
  else if (value && value.id) pending.push(value);
}
const unsafe = [];
for (const event of pending) {
  const reasons = [];
  const idempotency = event.idempotency_key || '';
  const eventTime = new Date(event.created_at).getTime();
  const blockedStatuses = ['sent', 'cancelled', 'dead_letter'];
  if (blockedStatuses.includes(event.status)) reasons.push('final_status_not_allowed');
  if (idempotency.startsWith('dev-test:')) reasons.push('dev_test_event');
  if (!cfg.allowed_event_types.includes(event.event_type)) reasons.push('event_type_not_allowed');
  if (!Number.isFinite(eventTime) || eventTime < minTime) reasons.push('historical_event_before_cutoff');
  if (!event.recipient_email) reasons.push('missing_recipient_email');
  if ((event.channel || '') !== 'email') reasons.push('channel_not_email');
  if (reasons.length) unsafe.push({ id: event.id, event_type: event.event_type, source_folio: event.source_folio, idempotency_key: idempotency, reasons });
}
return [{ json: {
  pending_count: pending.length,
  unsafe_count: unsafe.length,
  unsafe_events: unsafe,
  message: unsafe.length ? 'UNSAFE_PENDING_EVENTS_FOUND' : 'PREFLIGHT_OK'
} }];

const claimed = [];
for (const item of $input.all()) {
  const value = item.json;
  if (Array.isArray(value)) claimed.push(...value);
  else if (value && value.id) claimed.push(value);
}
if (!claimed.length) return [{ json: { flow_status: 'NO_EVENTS_CLAIMED', email_sent: false } }];
return [{ json: { flow_status: 'EVENT_CLAIMED', event: claimed[0] } }];

return [{ json: {
  workflow: 'Flux DEV - Notification Dispatcher EMAIL PILOT',
  flow_status: 'NO_EVENTS_CLAIMED',
  email_sent: false,
  pilot_mode: true
} }];

const cfg = $('Set Config').first().json;
const event = $json.event || {};
const payload = event.payload || {};
const errors = [];
const idempotency = event.idempotency_key || '';
const channel = event.channel || '';
const eventTime = new Date(event.created_at).getTime();
const minTime = new Date(cfg.FLUX_DEV_MIN_CREATED_AT).getTime();
const payloadText = JSON.stringify(payload).toLowerCase();
const sensitiveTokens = ['clabe', 'cuenta_bancaria', 'bank_account', 'account_number', 'numero_cuenta', 'convenio', 'token', 'password', 'secret', 'service' + '_role'];
if (!event.id) errors.push('missing_event_id');
if (!cfg.allowed_event_types.includes(event.event_type)) errors.push('event_type_not_allowed');
if (!event.recipient_email) errors.push('missing_recipient_email');
if (channel !== 'email') errors.push('channel_not_email');
if (!Number.isFinite(eventTime) || eventTime < minTime) errors.push('event_created_before_cutoff');
const blockedStatuses = ['sent', 'cancelled', 'dead_letter'];
if (blockedStatuses.includes(event.status)) errors.push(`event_final_status_not_allowed:${event.status}`);
if (event.status && event.status !== 'processing') errors.push(`status_not_processing:${event.status}`);
if (idempotency.startsWith('dev-test:')) errors.push('dev_test_event_not_allowed');
if (sensitiveTokens.some((token) => payloadText.includes(token))) errors.push('sensitive_payload_detected');
return [{ json: {
  safety_ok: errors.length === 0,
  error_message: errors.join('; '),
  event_id: event.id || null,
  event,
  payload
} }];

return [{ json: {
  workflow: 'Flux DEV - Notification Dispatcher EMAIL PILOT',
  flow_status: 'FAILED_SAFETY_FILTER',
  event_id: $('Safety Filter').first().json.event_id,
  error_message: $('Safety Filter').first().json.error_message,
  email_sent: false,
  pilot_mode: true
} }];

const cfg = $('Set Config').first().json;
const event = $('Safety Filter').first().json.event;
const payload = $('Safety Filter').first().json.payload || {};
const folio = payload.folio || event.source_folio || 'sin folio';
const comment = payload.comment || payload.comentario || payload.reason || '';
const amount = payload.monto || payload.amount || payload.amount_requested || 'N/D';
const currency = payload.moneda || payload.currency || 'MXN';
const link = payload.link_solicitud || 'https://catalogo-proveedores-flux-git-dev-quantta-team.vercel.app/solicitudes.html';
const common = [
  `Folio: ${folio}`,
  `Evento: ${event.event_type}`,
  `Monto: ${amount} ${currency}`,
  payload.solicitante ? `Solicitante: ${payload.solicitante}` : null,
  payload.proveedor ? `Proveedor: ${payload.proveedor}` : null,
  payload.empresa ? `Empresa: ${payload.empresa}` : null,
  payload.centro_costo ? `Centro de costo: ${payload.centro_costo}` : null,
  payload.partida ? `Partida: ${payload.partida}` : null,
  payload.mes ? `Mes: ${payload.mes}` : null,
  comment ? `Comentario: ${comment}` : null,
  `Link: ${link}`
].filter(Boolean).join('\n');
const templates = {
  'payment_request.created': {
    subject: `Nueva solicitud de pago: ${folio}`,
    intro: 'Nueva solicitud registrada.'
  },
  'payment_request.approved': {
    subject: `Solicitud aprobada: ${folio}`,
    intro: 'La solicitud fue aprobada.'
  },
  'payment_request.rejected': {
    subject: `Solicitud rechazada: ${folio}`,
    intro: 'La solicitud fue rechazada.'
  },
  'payment_request.changes_requested': {
    subject: `Se requieren cambios en la solicitud: ${folio}`,
    intro: 'Se solicitaron cambios en la solicitud.'
  },
  'payment_request.exception_approved': {
    subject: `Excepcion presupuestal autorizada: ${folio}`,
    intro: 'La excepcion presupuestal fue autorizada.'
  },
  'payment_request.exception_rejected': {
    subject: `Excepcion presupuestal rechazada: ${folio}`,
    intro: 'La excepcion presupuestal fue rechazada.'
  }
};
const template = templates[event.event_type] || { subject: `Notificacion Flux: ${folio}`, intro: 'Actualizacion de solicitud.' };
let finalRecipient = null;
if (cfg.SEND_TO_TEST_EMAIL_ONLY === true && cfg.SEND_TO_REAL_RECIPIENT !== true) finalRecipient = cfg.TEST_RECIPIENT_EMAIL;
if (cfg.SEND_TO_REAL_RECIPIENT === true && cfg.SEND_TO_TEST_EMAIL_ONLY !== true) finalRecipient = event.recipient_email;
if (!finalRecipient || !String(finalRecipient).includes('@')) throw new Error('EMAIL_RECIPIENT_MODE_INVALID');
const body = [
  'Flux Operadora - DEV EMAIL PILOT',
  '',
  cfg.SEND_TO_TEST_EMAIL_ONLY ? `Modo piloto: este correo se envia al correo interno de prueba. Destinatario original: ${event.recipient_email}` : 'Envio a destinatario real autorizado.',
  '',
  template.intro,
  '',
  common,
  '',
  'No responder a este correo automatico.'
].join('\n');
return [{ json: {
  event_id: event.id,
  event_type: event.event_type,
  source_folio: event.source_folio || folio,
  original_recipient_email: event.recipient_email,
  final_recipient_email: finalRecipient,
  rendered_subject: template.subject,
  rendered_body: body,
  pilot_mode: cfg.EMAIL_PILOT_MODE,
  sent_to_test_email_only: cfg.SEND_TO_TEST_EMAIL_ONLY
} }];

const rendered = $('Render Email Template').first().json;
const current = $input.first().json || {};
const failed = Boolean(current.error || current.message?.includes?.('Error'));
return [{ json: {
  ...rendered,
  email_ok: !failed,
  email_error: failed ? JSON.stringify(current.error || current).slice(0, 1000) : null,
  provider_message_id: `email-pilot:${$execution.id}:${rendered.event_id}`
} }];

const rendered = $('Normalize Email Result').first().json;
return [{ json: {
  workflow: 'Flux DEV - Notification Dispatcher EMAIL PILOT',
  email_sent: true,
  pilot_mode: true,
  sent_to_test_email_only: rendered.sent_to_test_email_only,
  event_id: rendered.event_id,
  event_type: rendered.event_type,
  source_folio: rendered.source_folio,
  original_recipient_email: rendered.original_recipient_email,
  final_recipient_email: rendered.final_recipient_email,
  provider_message_id: rendered.provider_message_id
} }];

const rendered = $('Normalize Email Result').first().json;
return [{ json: {
  workflow: 'Flux DEV - Notification Dispatcher EMAIL PILOT',
  email_sent: false,
  pilot_mode: true,
  event_id: rendered.event_id,
  event_type: rendered.event_type,
  source_folio: rendered.source_folio,
  original_recipient_email: rendered.original_recipient_email,
  final_recipient_email: rendered.final_recipient_email,
  error_message: rendered.email_error || 'email_send_failed'
} }];
